const params=new URLSearchParams(location.search);const topic=params.get('topic');const subject=params.get('subject')||'number-system';const data=lessons[topic];const subjectUrl='subject.html?subject='+encodeURIComponent(subject);
const el=id=>document.getElementById(id);
el('backSubject').href=subjectUrl;el('crumbSubject').href=subjectUrl;
function escapeHtml(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function showError(){el('lessonTitle').textContent='Lesson coming soon';el('lessonIntro').textContent='This topic has not been added yet. Return to the subject page and choose another topic.';el('lessonContent').innerHTML='<div class="lesson-error"><a href="'+subjectUrl+'">← Back to Number System</a></div>';['exampleContent','quizContent','revisionList'].forEach(id=>el(id).innerHTML='');}
function render(){if(!data){showError();return;}document.title=data.title+' — Transition Phase';el('lessonTitle').textContent=data.title;el('lessonIntro').textContent=data.intro;el('lessonCategory').textContent=subject.toUpperCase().replace(/-/g,' ')+' / '+topic.toUpperCase().replace(/-/g,' ');el('lessonContent').innerHTML=data.sections.map(([h,p])=>'<article class="concept-card"><h3>'+escapeHtml(h)+'</h3><p>'+escapeHtml(p)+'</p></article>').join('');el('exampleContent').innerHTML=data.examples.map(([h,q,a])=>'<article class="example-card"><h3>'+escapeHtml(h)+'</h3><p><b>'+escapeHtml(q)+'</b></p><p>'+escapeHtml(a)+'</p></article>').join('');el('quizContent').innerHTML=data.questions.map((q,i)=>'<article class="question-card" data-q="'+i+'"><h3>'+(i+1)+'. '+escapeHtml(q[0])+'</h3><div class="question-options">'+q[1].map((option,j)=>'<label class="question-option"><input type="radio" name="q'+i+'" value="'+j+'"><span>'+String.fromCharCode(65+j)+'. '+escapeHtml(option)+'</span></label>').join('')+'</div><div class="question-feedback" hidden></div></article>').join('');el('revisionList').innerHTML=data.revision.map(x=>'<li>'+escapeHtml(x)+'</li>').join('');}
function submit(){let score=0;data.questions.forEach((q,i)=>{const card=document.querySelector('[data-q="'+i+'"]');const selected=card.querySelector('input:checked');const feedback=card.querySelector('.question-feedback');const correct=selected&&Number(selected.value)===q[2];if(correct)score++;feedback.hidden=false;feedback.className='question-feedback '+(correct?'correct':'incorrect');feedback.textContent=(correct?'Correct. ':'Not quite. Correct answer: '+String.fromCharCode(65+q[2])+'. '+q[1][q[2]]+'. ')+q[3];});el('quizScore').textContent='Your score: '+score+' / '+data.questions.length;el('submitQuiz').hidden=true;el('retryQuiz').hidden=false;}
el('submitQuiz').addEventListener('click',submit);el('retryQuiz').addEventListener('click',()=>{document.querySelectorAll('.question-card input').forEach(x=>x.checked=false);document.querySelectorAll('.question-feedback').forEach(x=>x.hidden=true);el('quizScore').textContent='';el('submitQuiz').hidden=false;el('retryQuiz').hidden=true;});
el('markComplete').addEventListener('click',()=>{if(!data)return;const key='tp-topic-progress-'+subject;const saved=JSON.parse(localStorage.getItem(key)||'[]');const topicOrder=subject==='number-system'?['types-of-numbers','place-value','divisibility','factors-multiples','hcf-lcm','remainders']:subject==='mathematics'?['simplification','fractions-decimals','percentage','ratio-proportion','profit-loss-discount','simple-compound-interest','average','ages','time-work','pipes-cisterns','partnership','mixture-alligation','time-speed-distance','mensuration','geometry','trigonometry-heights-distances','data-interpretation'] : [];const idx=topicOrder.indexOf(topic);if(idx>=0&&!saved.includes(idx)){saved.push(idx);localStorage.setItem(key,JSON.stringify(saved));}el('completeMessage').textContent='Topic marked complete. Progress saved on this browser.';});
render();